import fs from 'node:fs';
import path from 'node:path';
export function compileBlueprintsAndContext(url, siteName, tokens, motion, sections, media, outDir) {
    const blueprintsDir = path.join(outDir, 'blueprints');
    const componentsDir = path.join(blueprintsDir, 'components');
    fs.mkdirSync(componentsDir, { recursive: true });
    // 1. Save sections.json
    fs.writeFileSync(path.join(blueprintsDir, 'sections.json'), JSON.stringify(sections, null, 2), 'utf8');
    // 2. Write AI-CONTEXT.md (Master AI & Developer Specification)
    const aiContext = `# ${siteName.toUpperCase()} — Extracted Design System & Motion Architecture (AI-CONTEXT)

> **Source URL:** \`${url}\`
> **Generated by:** Design Forge Reverse-Engineering Pipeline (Playwright + CDP)
> **Target Stack:** Astro + GSAP (ScrollTrigger) + Lenis Smooth Scroll + Tailwind CSS

---

## 1. Executive Summary for AI Coding Agents

When generating any new website using this **${siteName}** Design System, **DO NOT** output generic AI layouts. You must strictly adhere to the mathematical tokens, spatial grid ratios, surface physics, and motion choreography documented in this folder:

- **Tokens:** Import \`./tokens/tokens.css\` and \`./tokens/tailwind.preset.mjs\`.
- **Motion Engine:** Import \`./motion/gsap-choreography.ts\` (uses **Lenis** smooth scroll coupled to **GSAP ScrollTrigger** and \`cubic-bezier(0.16, 1, 0.3, 1)\` card physics).
- **Section Blueprints:** Use the parameterized Astro components in \`./blueprints/components/\` (\`MegaNav.astro\`, \`HeroStage.astro\`, \`BentoShowcase.astro\`, \`FeatureTabs.astro\`, \`MarqueeFooter.astro\`).
- **Visual Media Prompts:** Use \`./media-prompts/nano-banana-prompts.md\` and \`./media-prompts/google-flow-prompts.md\` so every image and video loop respects the exact aspect ratio and text-overlay safe zones.

---

## 2. Core Visual & Spatial DNA Extracted from \`${url}\`

### A. Typography Hierarchy
- **Primary Detected Font Stack:** \`${tokens.fontFamilies.slice(0, 4).join(', ') || 'Adobe Clean, Inter, system-ui'}\`
- **Display Hero (\`--df-text-hero\`):** \`clamp(2.75rem, 5.2vw, 4.75rem)\`, weight \`800\`, line-height \`1.04\`, letter-spacing \`-0.03em\`. Tight tracking and high weight create authority without clutter.
- **Section Heading XL (\`--df-text-h1\`):** \`clamp(2rem, 3.6vw, 3.25rem)\`, weight \`700\`, line-height \`1.08\`, letter-spacing \`-0.025em\`.
- **Bento Card Title (\`--df-text-h2\`):** \`clamp(1.5rem, 2.4vw, 2.15rem)\`, weight \`700\`, line-height \`1.15\`.
- **Eyebrow / Category Pill (\`--df-text-eyebrow\`):** \`0.78rem\`, uppercase, letter-spacing \`0.08em\`, weight \`700\`.

### B. Surface Physics & Color Architecture
- **High-Contrast Stage Alternation:** Alternates between crisp light canvases (\`rgb(255, 255, 255)\` / \`rgb(245, 245, 247)\`) and deep cinematic dark stages (\`#0E0E12\` / \`#18181E\`).
- **Glassmorphism:** Navigation bars, floating media controls, and badge pills use \`backdrop-filter: blur(20px) saturate(180%)\` with subtle \`1px solid rgba(255, 255, 255, 0.14)\` borders.
- **Card Elevation:** \`border-radius: 24px\` on flagship Bento cards, \`9999px\` on all primary/secondary CTA pills.

### C. Asymmetric Bento Grid Math
- **Container Max-Width:** \`1440px\` centered with \`24px\` (mobile) to \`48px\` (desktop) horizontal gutter.
- **12-Column Asymmetric Spans:**
  - **Row 1:** \`col-span-12 lg:col-span-8\` (Flagship interactive video/image card) + \`col-span-12 lg:col-span-4\` (High-contrast vertical spotlight card).
  - **Row 2:** Three equal \`col-span-12 md:col-span-4\` cards OR \`col-span-4\` + \`col-span-8\` inverted split.
  - **Grid Gap:** \`24px\` (\`1.5rem\`).
  - **Internal Card Padding:** \`32px\` to \`40px\`, with text anchored at the top-left and visual media filling the full bleed or lower 60% stage.

---

## 3. Extracted Motion & Animation Rules (\`motion/motion-dna.json\`)

- **Detected Easing Curves:** \`${motion.uniqueEasingCurves.slice(0, 6).join(' | ') || 'cubic-bezier(0.16, 1, 0.3, 1)'}\`
- **Detected Durations:** \`${motion.uniqueDurations.slice(0, 8).join(', ') || '180ms, 350ms, 550ms'}\`
- **Card Hover Interaction:**
  1. Card container translates \`translate3d(0, -6px, 0)\` with ambient shadow expansion.
  2. Inner background video/image scales \`1.045x\` over \`550ms cubic-bezier(0.16, 1, 0.3, 1)\`.
  3. Embedded Google Flow \`<video>\` plays seamlessly on hover or viewport intersection.
  4. CTA arrow nudges \`+5px\` horizontally.

---

## 4. Extracted Page Section Map (${sections.length} Structural Blocks)

${sections
        .map((s) => `- **Section ${s.index} (\`${s.archetype}\`)**: \`${s.selectorHint}\` | Size: \`${s.boundingBox.width}×${s.boundingBox.height}px\` | Cards: \`${s.cards.length}\` | Headings: ${s.headings.slice(0, 2).map((h) => `"${h}"`).join(', ') || 'N/A'}`)
        .join('\n')}

---

## 5. How to Build a New Brand Website From This Folder

1. Copy or reference \`tokens/tokens.css\` and override only \`--df-accent-primary\`, \`--df-accent-interactive\`, and \`--df-accent-gradient\` for the new brand.
2. Assemble the page using the Astro blueprints in \`blueprints/components/\`.
3. Generate custom visuals using the slot-matched prompts in \`media-prompts/nano-banana-prompts.md\` and \`media-prompts/google-flow-prompts.md\`.
4. Call \`bootDesignSystemMotion()\` from \`motion/gsap-choreography.ts\` in your client script.
`;
    fs.writeFileSync(path.join(outDir, 'AI-CONTEXT.md'), aiContext, 'utf8');
}
